import { createSlice, type PayloadAction } from '@reduxjs/toolkit';

type Todo = { id: string; title: string };
type TodosState = { items: Todo[]; lastAddedId: string | null };

const initialState: TodosState = { items: [], lastAddedId: null };

const todosSlice = createSlice({
  name: 'todos',
  initialState,
  reducers: {
    todoAdded(state, action: PayloadAction<Todo>) {
      state.items.push(action.payload);
      return { ...state, lastAddedId: action.payload.id };
    },
  },
});

export const { todoAdded } = todosSlice.actions;
export default todosSlice.reducer;

import { createAsyncThunk } from '@reduxjs/toolkit';
import { api, type ApiError } from '../api';
import type { Profile } from './types';

export const fetchProfile = createAsyncThunk(
  'profile/fetch',
  async (userId: string, { rejectWithValue }) => {
    try {
      const res = await api.get<Profile>(`/users/${userId}`);
      return res.data;
    } catch (err) {
      rejectWithValue((err as ApiError).message);
    }
  },
);

import { createSlice, type PayloadAction } from '@reduxjs/toolkit';

type SessionState = { userId: string | null; startedAt: Date | null };

const initialState: SessionState = { userId: null, startedAt: null };

export const sessionSlice = createSlice({
  name: 'session',
  initialState,
  reducers: {
    signedIn(state, action: PayloadAction<string>) {
      state.userId = action.payload;
      state.startedAt = new Date();
    },
  },
});

